"""Third append-only authored foundations batch, using explicit fixture contracts.

This author never fills a numeric gap by multiplying scenario names or values.
Every row defines a separate observable responsibility or a labelled transfer.
"""
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
BANK=ROOT/'tools/problem-bank'
VERSION='2026.10.26.2'
ROWS={}

def author(tool,text):
    for line in text.strip().splitlines():
        if line.strip():
            level,title,task,inputs,output,edge=line.split('|')
            ROWS.setdefault(tool,[]).append((int(level),title,task,inputs,output,edge))

